import time

KOHONEN_I = [0, 5] + list(range(112, 138, 5))
KOHONEN_J = list(range(10, 107, 6))
KOHONEN_K = list(range(0, 5)) + list(range(224, 230)) + list(range(367, 373))


def m_of(I, J, K):
    IJ = {a + b for a in I for b in J}
    IK = {a + b for a in I for b in K}
    JK = {a + b for a in J for b in K}
    sq = IJ | IK
    m = 0
    while m in sq or (m in JK and (m - 1) in JK):
        m += 1
    return m


def ratio(I, J, K):
    l = len(I) + len(J) + len(K)
    return m_of(I, J, K) / (l * l)


def search(prev_best, deadline, rng):
    """SEED: Kohonen's placement + naive random single-element hill climbing.

    Deliberately weak — it only jiggles one integer at a time and never changes
    the SHAPE of the placement. Everything interesting lives in the shape."""
    if prev_best:
        I, J, K = list(prev_best["I"]), list(prev_best["J"]), list(prev_best["K"])
    else:
        I, J, K = list(KOHONEN_I), list(KOHONEN_J), list(KOHONEN_K)
    best = (I[:], J[:], K[:])
    bs = ratio(*best)

    while time.time() < deadline:
        I, J, K = [list(x) for x in best]
        tgt = rng.choice([I, J, K])
        if not tgt:
            continue
        i = rng.randrange(len(tgt))
        tgt[i] = max(0, tgt[i] + rng.choice([-3, -2, -1, 1, 2, 3]))
        cand = (sorted(set(I)), sorted(set(J)), sorted(set(K)))
        if any(len(x) == 0 for x in cand):
            continue
        r = ratio(*cand)
        if r >= bs:
            best, bs = cand, r
    return {"I": best[0], "J": best[1], "K": best[2]}

import time

def m_of(I, J, K):
    IJ = {a + b for a in I for b in J}
    IK = {a + b for a in I for b in K}
    JK = {a + b for a in J for b in K}
    sq = IJ | IK
    m = 0
    while m in sq or (m in JK and (m - 1) in JK):
        m += 1
    return m

def ratio(I, J, K):
    l = len(I) + len(J) + len(K)
    return m_of(I, J, K) / (l * l) if l else 0.0

def search(prev_best, deadline, rng):
    """ALGORITHMIC LENS: simulated annealing over placements, with the SPLIT
    itself as a search variable.

    Kohonen's 8/17/17 split caps him at 0.318; a balanced split caps at 0.3333.
    So we do NOT hold the split fixed — moves may add to or delete from any of
    I, J, K, letting the annealer discover the right shape rather than assuming
    Kohonen's. Objective is m/l^2 directly (the true target), with restarts."""
    best_obj, best_r = None, -1.0
    if prev_best:
        I0 = list(prev_best["I"]); J0 = list(prev_best["J"]); K0 = list(prev_best["K"])
        best_obj, best_r = (I0, J0, K0), ratio(I0, J0, K0)

    def perturb(I, J, K):
        I, J, K = list(I), list(J), list(K)
        which = rng.choice([I, J, K])
        op = rng.random()
        if op < 0.42 and which:                 # move an element
            i = rng.randrange(len(which))
            which[i] = max(0, which[i] + rng.choice([-8,-5,-3,-2,-1,1,2,3,5,8]))
        elif op < 0.71:                          # add an element
            span = max(max(I+J+K), 10)
            which.append(rng.randrange(0, span + 6))
        elif which and len(which) > 2:           # delete an element
            which.pop(rng.randrange(len(which)))
        return sorted(set(I)), sorted(set(J)), sorted(set(K))

    T0, T1 = 0.010, 0.0004
    while time.time() < deadline:
        # restart from incumbent (or a fresh balanced random placement)
        if best_obj and rng.random() < 0.6:
            cur = tuple(list(x) for x in best_obj)
        else:
            n = rng.randrange(4, 16)
            cur = (sorted({rng.randrange(0, 60) for _ in range(n)}),
                   sorted({rng.randrange(0, 120) for _ in range(n)}),
                   sorted({rng.randrange(0, 200) for _ in range(n)}))
            if any(len(x) < 2 for x in cur):
                continue
        cr = ratio(*cur)
        steps = 2600
        for s in range(steps):
            if time.time() > deadline:
                break
            T = T0 * (T1 / T0) ** (s / steps)
            cand = perturb(*cur)
            if any(len(x) < 2 for x in cand):
                continue
            r = ratio(*cand)
            if r >= cr or rng.random() < pow(2.718281828, (r - cr) / T):
                cur, cr = cand, r
                if r > best_r:
                    best_r, best_obj = r, tuple(list(x) for x in cand)
    I, J, K = best_obj
    return {"I": I, "J": J, "K": K}
